window.Editor=(()=>{
 const {e,icon,button,badge,field,input,select,empty}=UI;
 let state=null;const drafts=new Map();
 function open(id){if(state?.key===id)return;if(state)drafts.set(state.key,state);if(drafts.has(id)){state=drafts.get(id);return;}const existing=Cousins.getPreset(id);const p=existing?Cousins.clone(existing):{id:'preset-'+Date.now(),name:'Untitled preset',revision:0,family:'Custom',profile:'Custom',devices:['ms-1'],policy:'continue',views:[{id:'view-1',name:'Overview',components:[]}]};state={key:id,preset:p,view:p.views[0].id,selected:'',tab:'data',picker:false,inspector:false,dirty:!existing,history:[],future:[]};}
 function view(){return state.preset.views.find(v=>v.id===state.view)||state.preset.views[0];}
 function selected(){return Layout.find(view().components,state.selected)?.component;}
 function checkpoint(){state.history.push(JSON.stringify(state.preset));state.history=state.history.slice(-40);state.future=[];state.dirty=true;}
 function choice(label,name,value,values){return field(label,select(name,value,values,`data-edit="${name}"`));}
 function inp(label,name,value,type='text',attrs=''){return field(label,input(name,value,type,`data-edit="${name}" ${attrs}`));}
 function inspector(){const c=selected();if(!state.inspector||!c)return '';const targets=[{value:'root',label:'View'}];Layout.walk(view().components,x=>{if(x.kind==='group'&&x.id!==c.id&&!Layout.find(c.children||[],x.id))targets.push({value:x.id,label:x.title});});let content='';
 if(state.tab==='data')content=`${inp('Component name','title',c.title)}${c.kind!=='group'?choice('Device','device',c.device,Cousins.db.devices.map(d=>({value:d.id,label:d.name}))):''}${['chart','numeric'].includes(c.kind)?`<div class="field"><span>Channels</span><div class="channel-options">${(Cousins.getDevice(c.device)?.channels||[]).map(ch=>`<label class="channel-option"><input type="checkbox" data-channel="${ch.id}" ${c.channels.includes(ch.id)?'checked':''}><span class="channel-label"><strong>${e(ch.name)}</strong><span>${e(ch.unit)}<span class="shape-label">${ch.shape.startsWith('Vector')?'Vector':'Scalar'}</span></span></span></label>`).join('')}</div></div>${choice('Processing','process',c.process||'raw',[{value:'raw',label:'Raw stream'},{value:'linear',label:'Scale and offset'}])}${c.process==='linear'?`<div class="two-fields">${inp('Scale','gain',c.gain??1,'number','step="any"')}${inp('Offset','offset',c.offset??0,'number','step="any"')}</div><p class="field-hint">Derived = raw × scale + offset. Raw data is retained.</p>`:''}`:''}${c.kind==='chart'?`<div class="section-label">Additional streams</div>${(c.extraStreams||[]).map((stream,i)=>`<div class="field-editor">${field('Device',select('stream-device',stream.device,Cousins.db.devices.filter(d=>d.channels.length).map(d=>({value:d.id,label:d.name})),`data-stream="${i}" data-stream-key="device"`))}${field('Channel',select('stream-channel',stream.channel,Cousins.getDevice(stream.device)?.channels.map(ch=>({value:ch.id,label:ch.name+' · '+ch.unit}))||[],`data-stream="${i}" data-stream-key="channel"`))}${field('Processing',select('stream-process',stream.process||'raw',[{value:'raw',label:'Raw'},{value:'linear',label:'Scale and offset'}],`data-stream="${i}" data-stream-key="process"`))}${stream.process==='linear'?`<div class="two-fields">${field('Scale',input('gain',stream.gain??1,'number',`step="any" data-stream="${i}" data-stream-key="gain"`))}${field('Offset',input('offset',stream.offset??0,'number',`step="any" data-stream="${i}" data-stream-key="offset"`))}</div>`:''}${button('Remove stream','stream-remove',{id:String(i),quiet:true})}</div>`).join('')}${button('Add stream','stream-add',{icon:'plus'})}`:''}${c.kind==='results'?choice('Calculation profile','profile',c.profile||'Enzyme',['Enzyme','Gas','Isotope','Fluorescence']):''}${c.kind==='inputs'?`<div class="section-label">Fields</div>${(c.fields||[]).map((f,i)=>`<div class="field-editor">${field('Label',input('label',f.label,'text',`data-field-index="${i}" data-field-key="label"`))}<div class="two-fields">${field('Type',select('type',f.type,['text','number','select','boolean'],`data-field-index="${i}" data-field-key="type"`))}${field('Columns',select('span',String(f.span),['3','4','6','12'],`data-field-index="${i}" data-field-key="span"`))}</div>${f.type==='number'?`<div class="two-fields">${field('Unit',input('unit',f.unit||'','text',`data-field-index="${i}" data-field-key="unit"`))}${field('Step',input('step',f.step||1,'number',`data-field-index="${i}" data-field-key="step"`))}${field('Minimum',input('min',f.min??0,'number',`data-field-index="${i}" data-field-key="min"`))}${field('Maximum',input('max',f.max??100,'number',`data-field-index="${i}" data-field-key="max"`))}</div>`:''}${f.type==='select'?field('Options, one per line',`<textarea data-field-index="${i}" data-field-key="options">${e((f.options||[]).join('\n'))}</textarea>`):''}${button('Remove field','field-remove',{id:String(i),quiet:true,icon:'trash'})}</div>`).join('')}${button('Add field','field-add',{icon:'plus'})}`:''}`;
 if(state.tab==='display')content=c.kind==='chart'?`${choice('Chart type','chartType',c.chartType,[{value:'line',label:'Time series'},{value:'spectrum',label:'Spectrum'},{value:'scatter',label:'Scatter'}])}<div class="two-fields">${inp('Trace color','colorHex',c.colorHex||'#087f76','color')}${inp('Line weight','thickness',c.thickness||2,'number','min="1" max="6" step="1"')}</div><div class="two-fields">${inp('Axis minimum','axisMin',c.axisMin??'','number','step="any" placeholder="Auto"')}${inp('Axis maximum','axisMax',c.axisMax??'','number','step="any" placeholder="Auto"')}</div><label class="check-row"><input type="checkbox" data-edit="showLegend" ${c.showLegend!==false?'checked':''}>Show legend</label><label class="check-row"><input type="checkbox" data-edit="logScale" ${c.logScale?'checked':''}>Logarithmic axis</label>`:`<p class="field-hint">${c.kind==='numeric'?'The value inherits its channel unit.':'Content adapts to the component dimensions.'}</p>`;
 if(state.tab==='layout'){let parent='root';Layout.walk(view().components,(x,list)=>{if(list.includes(c)&&x.kind==='group'){}if(x.children?.includes(c))parent=x.id;});content=`<div class="two-fields">${inp('Column','x',c.x+1,'number','min="1" max="12"')}${inp('Row','y',c.y+1,'number','min="1" max="100"')}${inp('Column span','w',c.w,'number','min="2" max="12"')}${inp('Row span','h',c.h,'number','min="2" max="12"')}</div>${field('Container',select('parent',parent,targets,'data-parent-select'))}<p class="field-hint">Use arrow keys on the move handle. Hold Shift to resize. Components snap to a 12-column grid.</p>`;}
 if(state.tab==='behavior')content=(c.kind==='control'?choice('Control target','controlScope',c.controlScope||'device',[{value:'device',label:'This device'},{value:'group',label:'All devices in preset'}]):'')+`${field('On member failure',select('policy',state.preset.policy,[{value:'continue',label:'Continue remaining devices'},{value:'stop',label:'Stop all devices'}],'data-policy'))}<p class="field-hint">Parameter edits stay pending until Apply. Device commands are explicit.</p>${c.kind==='control'?badge('Commands unavailable in editor'):''}`;
 return `<aside class="inspector"><header><div><span class="eyebrow">${e(Layout.catalog.find(x=>x.kind===c.kind)?.name)}</span><h2>${e(c.title)}</h2></div>${button('Close inspector','inspector-close',{icon:'close',iconOnly:true})}</header><div class="inspector-tabs" role="tablist">${['data','display','layout','behavior'].map(tab=>`<button role="tab" aria-selected="${state.tab===tab}" class="${state.tab===tab?'active':''}" data-action="inspector-tab" data-id="${tab}">${tab[0].toUpperCase()+tab.slice(1)}</button>`).join('')}</div><div class="inspector-body">${content}</div><footer>${button('Duplicate','component-copy',{icon:'copy'})}${button('Remove','component-remove',{icon:'trash',danger:true})}</footer></aside>`;
 }
 function render(){const p=state.preset;return `<div class="editor-page"><header class="page-header"><div class="editor-name">${UI.breadcrumbs(p.name)}<input class="title-input" aria-label="Preset name" value="${e(p.name)}" data-preset-name><span class="quiet-label">${state.dirty?'Unsaved changes':'Saved · revision '+p.revision}</span></div><div class="actions">${button('Undo','undo',{icon:'undo',iconOnly:true,disabled:!state.history.length})}${button('Save preset','save-preset',{icon:'save'})}${button('Start collection','start-editor',{icon:'play',primary:true})}</div></header><div class="editor-work">${App.presetSidebar()}<div class="editor-main"><div class="editor-toolbar"><div class="view-tabs">${p.views.map(v=>`<button class="${v.id===state.view?'active':''}" data-action="editor-view" data-id="${v.id}">${e(v.name)}</button>`).join('')}${button('Add view','view-add',{icon:'plus',iconOnly:true})}</div><div class="actions">${button('Rename view','view-rename',{quiet:true})}<div class="picker-anchor">${button('Add component','picker',{icon:'plus'})}${state.picker?`<div class="component-picker"><input type="search" placeholder="Find a component" aria-label="Find a component" id="component-search"><div class="picker-items">${Layout.catalog.map(c=>`<button draggable="true" data-kind="${c.kind}" data-action="add-component" class="picker-item">${icon(c.icon)}<span><strong>${c.name}</strong><small>${c.description}</small></span></button>`).join('')}</div></div>`:''}</div></div></div><div class="canvas-scroll">${Components.grid(view().components,{editing:true,selected:state.selected})}<div class="canvas-footer"><span>12 columns</span><span>Drag to move · drag a corner to resize</span></div></div></div>${inspector()}</div></div>`;}
 function save(){if(!state.preset.name.trim()){App.toast('Enter a preset name.');return false;}const p=Cousins.clone(state.preset);const deviceIds=new Set();for(const v of p.views)Layout.walk(v.components,c=>{if(c.kind==='control'||['chart','numeric'].includes(c.kind)){deviceIds.add(c.device);for(const stream of c.extraStreams||[])deviceIds.add(stream.device);}});p.devices=[...deviceIds].filter(Boolean);if(!p.devices.length)p.devices=state.preset.devices;p.revision++;p.updated=new Date().toLocaleDateString();const i=Cousins.db.presets.findIndex(x=>x.id===p.id);if(i<0)Cousins.db.presets.unshift(p);else Cousins.db.presets[i]=p;drafts.delete(state.key);state.preset=p;state.key=p.id;state.dirty=false;Cousins.save();return true;}
 function action(action,id,element){if(!state)return false;const c=selected();
  if(action==='picker')state.picker=!state.picker;
  else if(action==='select-component'){state.selected=id;state.inspector=true;}
  else if(action==='inspector-close')state.inspector=false;
  else if(action==='inspector-tab')state.tab=id;
  else if(action==='add-component'){checkpoint();const item=Layout.create(element.dataset.kind,state.preset.devices[0]);const list=c?.kind==='group'?c.children:view().components;Layout.append(list,item);state.selected=item.id;state.inspector=true;state.picker=false;}
  else if(action==='component-remove'&&c){checkpoint();const found=Layout.find(view().components,c.id);found.list.splice(found.list.indexOf(c),1);state.selected='';state.inspector=false;}
  else if(action==='component-copy'&&c){checkpoint();const copy=Cousins.clone(c);Layout.walk([copy],x=>x.id='c-'+Math.random().toString(36).slice(2));Layout.append(Layout.find(view().components,c.id).list,copy);state.selected=copy.id;}
  else if(action==='editor-view'){state.view=id;state.selected='';state.inspector=false;}
  else if(action==='view-add'){checkpoint();const v={id:'view-'+Date.now(),name:'View '+(state.preset.views.length+1),components:[]};state.preset.views.push(v);state.view=v.id;state.selected='';}
  else if(action==='view-rename'){App.inlineName('View name',view().name,name=>{checkpoint();view().name=name;App.render();});return true;}
  else if(action==='save-preset'){if(save()){state.key=state.preset.id;App.ui.route='editor/'+state.preset.id;App.toast('Preset saved');}}
  else if(action==='start-editor'){if(save())App.navigate('start/'+state.preset.id);return true;}
  else if(action==='undo'){if(state.history.length){state.future.push(JSON.stringify(state.preset));state.preset=JSON.parse(state.history.pop());state.dirty=true;}}
  else if(action==='stream-add'&&c){checkpoint();c.extraStreams ||= [];const d=Cousins.db.devices.find(d=>d.channels.length);c.extraStreams.push({device:d.id,channel:d.channels[0].id,process:'raw'});}
  else if(action==='stream-remove'&&c){checkpoint();c.extraStreams.splice(Number(id),1);}
  else if(action==='field-add'&&c){checkpoint();c.fields.push({id:'field-'+Date.now(),label:'New field',type:'number',value:0,min:0,max:100,step:1,span:6,unit:''});}
  else if(action==='field-remove'&&c){checkpoint();c.fields.splice(Number(id),1);}
  else return false;App.render();return true;
 }
 function change(el){const c=selected();if(el.matches('[data-preset-name]')){checkpoint();state.preset.name=el.value;return true;}
 if(el.matches('[data-policy]')){checkpoint();state.preset.policy=el.value;return true;}
 if(!c)return false;
 if(el.hasAttribute('data-edit')){if(!el.checkValidity()){el.reportValidity();return true;}checkpoint();const key=el.dataset.edit;let value=el.type==='checkbox'?el.checked:el.type==='number'&&el.value!==''?Number(el.value):el.value;if(key==='x'||key==='y')value--;c[key]=value;if(key==='device')c.channels=Cousins.getDevice(value)?.channels.slice(0,1).map(x=>x.id)||[];if(['x','y','w','h'].includes(key))Layout.settle(Layout.find(view().components,c.id).list,c.id);App.render();return true;}
 if(el.hasAttribute('data-stream')){checkpoint();const stream=c.extraStreams[Number(el.dataset.stream)],key=el.dataset.streamKey;stream[key]=['gain','offset'].includes(key)?Number(el.value):el.value;if(key==='device')stream.channel=Cousins.getDevice(el.value).channels[0]?.id;App.render();return true;}
 if(el.hasAttribute('data-channel')){checkpoint();if(el.checked)c.channels.push(el.dataset.channel);else c.channels=c.channels.filter(x=>x!==el.dataset.channel);App.render();return true;}
 if(el.hasAttribute('data-field-index')){checkpoint();const key=el.dataset.fieldKey;c.fields[Number(el.dataset.fieldIndex)][key]=key==='options'?el.value.split('\n').filter(Boolean):['span','min','max','step'].includes(key)?Number(el.value):el.value;if(key==='type'&&el.value==='select')c.fields[Number(el.dataset.fieldIndex)].options=['Option 1','Option 2'];App.render();return true;}
 if(el.hasAttribute('data-parent-select')){checkpoint();const source=Layout.find(view().components,c.id).list;const target=el.value==='root'?view().components:Layout.find(view().components,el.value)?.component.children;if(target&&target!==source){source.splice(source.indexOf(c),1);Layout.append(target,c);}App.render();return true;}
 return false;
 }
 function mount(){document.getElementById('component-search')?.addEventListener('input',ev=>document.querySelectorAll('.picker-item').forEach(el=>el.hidden=!el.textContent.toLowerCase().includes(ev.target.value.toLowerCase())));
 document.querySelectorAll('[draggable=true]').forEach(el=>el.addEventListener('dragstart',ev=>{ev.dataTransfer.setData('text/plain',JSON.stringify(el.dataset.kind?{kind:el.dataset.kind}:{id:el.dataset.drag}));ev.dataTransfer.effectAllowed='move';}));
 document.querySelectorAll('[data-grid]').forEach(grid=>{grid.addEventListener('dragover',ev=>{ev.preventDefault();ev.stopPropagation();grid.classList.add('drop-target');});grid.addEventListener('dragleave',()=>grid.classList.remove('drop-target'));grid.addEventListener('drop',ev=>{ev.preventDefault();ev.stopPropagation();let payload;try{payload=JSON.parse(ev.dataTransfer.getData('text/plain'));}catch{return;}const target=grid.dataset.grid==='root'?view().components:Layout.find(view().components,grid.dataset.grid)?.component.children;if(!target)return;const found=payload.id?Layout.find(view().components,payload.id):null;if(found&&(grid.dataset.grid===payload.id||Layout.find(found.component.children||[],grid.dataset.grid)))return;checkpoint();const c=found?.component||Layout.create(payload.kind,state.preset.devices[0]);if(found)found.list.splice(found.list.indexOf(c),1);const rect=grid.getBoundingClientRect();c.x=Math.min(12-c.w,Math.max(0,Math.floor((ev.clientX-rect.left)/(rect.width/12))));c.y=Math.max(0,Math.floor((ev.clientY-rect.top)/92));target.push(c);Layout.settle(target,c.id);state.selected=c.id;state.inspector=true;state.picker=false;App.render();});});
 document.querySelectorAll('[data-resize]').forEach(handle=>handle.addEventListener('pointerdown',ev=>{ev.preventDefault();ev.stopPropagation();const found=Layout.find(view().components,handle.dataset.resize);if(!found)return;checkpoint();const c=found.component,tile=handle.closest('.bento-tile'),grid=tile.parentElement,rect=grid.getBoundingClientRect(),x=ev.clientX,y=ev.clientY,w=c.w,h=c.h;handle.setPointerCapture(ev.pointerId);const move=event=>{c.w=Math.min(12-c.x,Math.max(2,w+Math.round((event.clientX-x)/(rect.width/12))));c.h=Math.max(2,Math.min(12,h+Math.round((event.clientY-y)/92)));tile.style.gridColumn=`${c.x+1}/span ${c.w}`;tile.style.gridRow=`${c.y+1}/span ${c.h}`;};const up=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',up);Layout.settle(found.list,c.id);state.selected=c.id;App.render();};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',up);}));
 document.querySelectorAll('[data-drag],[data-resize]').forEach(el=>el.addEventListener('keydown',ev=>{if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(ev.key))return;ev.preventDefault();const id=el.dataset.drag||el.dataset.resize,found=Layout.find(view().components,id);checkpoint();const resize=ev.shiftKey||el.hasAttribute('data-resize');found.component[ev.key==='ArrowLeft'||ev.key==='ArrowRight'?(resize?'w':'x'):(resize?'h':'y')]+=ev.key==='ArrowLeft'||ev.key==='ArrowUp'?-1:1;Layout.settle(found.list,id);App.render();document.querySelector(`[data-${el.hasAttribute('data-resize')?'resize':'drag'}="${id}"]`)?.focus();}));
 }
 return {open,render,mount,action,change,view,selected,checkpoint,save,get state(){return state;}};
})();
